import { revalidateTag } from 'next/cache';

export async function getPosts() {
  // Use Next.js modern caching with 1 hour duration and "posts" tag
  const cachedPosts = await fetch('http://localhost:3000/api/posts-cache', {
    next: {
      revalidate: 3600, // 1 hour in seconds
      tags: ['posts']
    }
  }).then(res => res.json());

  return cachedPosts;
}

// Helper function to invalidate posts cache on-demand
export function invalidatePostsCache() {
  revalidateTag('posts');
}

